@php use App\Support\Format; @endphp
{{-- Fleet-level readouts for a shift: every figure is derived from the Dot.Mines mirror. --}}
<div class="dot-panels dot-panels--6" style="margin-bottom:1.25rem;">
    <div class="dot-panel dot-readout"><span class="dot-readout__label">Operating now</span><span class="dot-readout__value dot-readout__value--ok">{{ Format::integer($totals['by_state']['operating'] ?? 0) }}<span class="dot-readout__unit">/ {{ $totals['units'] ?? 0 }}</span></span><span class="dot-readout__context">{{ ($totals['by_state']['unknown'] ?? 0) }} unknown · {{ ($totals['by_state']['stale'] ?? 0) }} stale</span></div>
    <div class="dot-panel dot-readout"><span class="dot-readout__label">Run hours</span><span class="dot-readout__value">{{ Format::number($totals['run_hours'] ?? null) }}</span><span class="dot-readout__context">{{ $totals['with_reading'] ?? 0 }} of {{ $totals['units'] ?? 0 }} with readings · idle {{ Format::number($totals['idle_hours'] ?? null) }} h</span></div>
    <div class="dot-panel dot-readout"><span class="dot-readout__label">Loads</span><span class="dot-readout__value">{{ Format::integer($totals['loads'] ?? null) }}</span><span class="dot-readout__context">from cumulative load counters</span></div>
    <div class="dot-panel dot-readout"><span class="dot-readout__label">Production</span><span class="dot-readout__value">{{ Format::number($totals['production_quantity'] ?? null, 0) }}<span class="dot-readout__unit">{{ $totals['production_unit'] ?? '' }}</span></span><span class="dot-readout__context">Dot.Mines production records</span></div>
    <div class="dot-panel dot-readout"><span class="dot-readout__label">Stoppage</span><span class="dot-readout__value {{ ($totals['stoppage_minutes'] ?? 0) > 0 ? 'dot-readout__value--warn' : '' }}">{{ Format::number(($totals['stoppage_minutes'] ?? 0) / 60, 1) }}<span class="dot-readout__unit">h</span></span><span class="dot-readout__context">offline or maintenance, observed</span></div>
    <div class="dot-panel dot-readout"><span class="dot-readout__label">Stopped now</span><span class="dot-readout__value {{ count($totals['stopped_now'] ?? []) ? 'dot-readout__value--bad' : '' }}">{{ Format::integer(count($totals['stopped_now'] ?? [])) }}</span><span class="dot-readout__context">{{ collect($totals['stopped_now'] ?? [])->pluck('name')->take(4)->implode(', ') ?: 'none' }}</span></div>
</div>
